\begin{exercise}
\textbf{Question.} A 6 V supply is connected across three identical $2\,\Omega$ resistors in series. Point B, at the negative terminal, is earthed. Find the potentials after the first and second resistors when moving from the positive terminal.

\begin{center}
  \begin{circuitikz}[x=1cm, y=1cm, line width=1pt]
    \draw (0,0) to[battery1, l=6 V] (0,3);
    \draw (0,3) to[R, l=$2\,\Omega$] (2,3) to[R, l=$2\,\Omega$] (4,3) to[R, l=$2\,\Omega$] (6,3);
    \draw (6,3) to[short] (6,0);
    \node[ground, scale=0.8] at (6,0) {};
    \node[right] at (6.2,0.2) {$B\,(0\text{ V})$};
    \draw (0,0) to[short] (6,0);
    \node[above] at (2,3.3) {$P$};
    \node[above] at (4,3.3) {$Q$};
  \end{circuitikz}
  \qquad
  \begin{tikzpicture}[x=1cm,y=1cm]
    \draw[->] (0,0) -- (5,0) node[right] {position around circuit};
    \draw[->] (0,0) -- (0,3.5) node[above] {potential};
    \draw[very thick] (0.5,0.5) -- (1.3,0.5);
    \draw[very thick,->] (1.3,0.5) -- (1.3,2.8) node[midway,right] {cell: rise 6 V};
    \draw[very thick] (1.3,2.8) -- (2.8,2.8);
    \draw[very thick,->] (2.8,2.8) -- (2.8,2.1) node[midway,right] {drop 2 V};
    \draw[very thick] (2.8,2.1) -- (4.2,2.1);
    \draw[very thick,->] (4.2,2.1) -- (4.2,1.4) node[midway,right] {drop 2 V};
    \draw[very thick] (4.2,1.4) -- (5,1.4);
  \end{tikzpicture}
  \caption{Left: circuit with earth symbol at B. Right: potential ladder showing potential at each point (relative to earth).}
\end{center}

\textbf{Solution.} Earthing sets $V_B=0$, but does not by itself change the currents. The three equal resistors share 6 V equally, so each drop is 2 V. Starting from the positive terminal ($+6$ V), the potential decreases by 2 V after each resistor: $+4$ V at $P$, $+2$ V at $Q$, and $0$ V at $B$.
\end{exercise}

