\myskip
\begin{exercise}
\textbf{Question.} Four wires meet at the junction $P$ shown below. A current of $4.0$ A flows in from the left and $1.5$ A flows in from the top. A current of $2.5$ A leaves downward. Find the current $I$ in the right-hand wire, and state its direction.

\begin{center}
  \begin{tikzpicture}[x=1cm, y=1cm, >=stealth, line width=1pt]
    % wires
    \draw (-2.5,0) -- (2.5,0);
    \draw (0,2.5) -- (0,-2.5);
    \node[circle,fill,inner sep=1.4pt] at (0,0) {};
    \node[above right] at (0,0) {$P$};
    % current arrows
    \draw[->,blue!70!black,line width=1.2pt] (-2.1,0.32) -- (-0.9,0.32)
      node[midway,above,font=\footnotesize] {$4.0$ A};
    \draw[->,blue!70!black,line width=1.2pt] (-0.32,2.1) -- (-0.32,0.9)
      node[midway,left,font=\footnotesize] {$1.5$ A};
    \draw[->,blue!70!black,line width=1.2pt] (0.9,0.32) -- (2.1,0.32)
      node[midway,above,font=\footnotesize] {$I$};
    \draw[->,blue!70!black,line width=1.2pt] (-0.32,-0.9) -- (-0.32,-2.1)
      node[midway,left,font=\footnotesize] {$2.5$ A};
  \end{tikzpicture}
  \captionof{figure}{Currents meeting at junction $P$. Two currents flow in, one flows out downward, and $I$ is unknown.}
\end{center}

\textbf{Solution.} Charge cannot build up at $P$, so the current flowing in equals the current flowing out. The currents in are $4.0+1.5=5.5$ A, and so far only $2.5$ A has been accounted for leaving. The rest must leave through the right-hand wire:
\[
I = (4.0+1.5) - 2.5 = \boxed{3.0\text{ A}},
\]
directed \emph{out} of the junction (to the right). If the arithmetic had given a negative value, it would simply mean the current actually flows the other way.
\end{exercise}

